import React, { useEffect, useMemo, useRef, useState } from 'react';
import { io } from 'socket.io-client';
import { api, normalizeArrayPayload, normalizeTrades, normalizeTraderDetail, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function TraderTrendChart({ points, predictedTrust }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const width = canvas.offsetWidth || 760;
    canvas.width = width * 2;
    canvas.height = 260 * 2;
    canvas.style.height = '260px';

    const ctx = canvas.getContext('2d');
    ctx.scale(2, 2);
    ctx.clearRect(0, 0, width, 260);

    if (!points.length) {
      ctx.fillStyle = '#65705f';
      ctx.font = '14px Inter';
      ctx.fillText('No trade history for this trader yet', 18, 130);
      return;
    }

    const pad = 24;
    const chartW = width - pad * 2;
    const chartH = 180;

    const maxX = Math.max(1, points.length - 1);

    const mapPoint = (i, value) => ({
      x: pad + (i / maxX) * chartW,
      y: pad + chartH - (Math.max(0, Math.min(100, value)) / 100) * chartH,
    });

    for (let i = 0; i <= 4; i += 1) {
      const y = pad + (chartH / 4) * i;
      ctx.strokeStyle = 'rgba(255,255,255,0.05)';
      ctx.beginPath();
      ctx.moveTo(pad, y);
      ctx.lineTo(width - pad, y);
      ctx.stroke();
    }

    const riskPts = points.map((p, i) => mapPoint(i, p.risk_score));
    const trustPts = points.map((p, i) => mapPoint(i, p.trust_score));

    const drawLine = (pts, color) => {
      ctx.beginPath();
      pts.forEach((p, i) => {
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.strokeStyle = color;
      ctx.lineWidth = 3;
      ctx.shadowColor = color;
      ctx.shadowBlur = 14;
      ctx.stroke();
      ctx.shadowBlur = 0;
    };

    drawLine(riskPts, '#ff5555');
    drawLine(trustPts, '#b8ff4f');

    const predX = width - pad;
    const predY = pad + chartH - (predictedTrust / 100) * chartH;
    ctx.beginPath();
    ctx.arc(predX, predY, 5, 0, Math.PI * 2);
    ctx.fillStyle = '#d8ff91';
    ctx.fill();
    ctx.fillStyle = '#d8ff91';
    ctx.font = '12px Inter';
    ctx.fillText(`Pred Trust ${predictedTrust}`, predX - 92, predY - 10);

    ctx.fillStyle = '#ff7c7c';
    ctx.fillRect(pad, 220, 14, 3);
    ctx.fillStyle = '#95ff2e';
    ctx.fillRect(132, 220, 14, 3);
    ctx.fillStyle = '#7c8576';
    ctx.font = '12px Inter';
    ctx.fillText('Risk Score', 34, 224);
    ctx.fillText('Trust Score', 154, 224);
  }, [points, predictedTrust]);

  return <canvas ref={canvasRef} style={{ width: '100%', display: 'block' }} />;
}

export default function TradersPage() {
  const [traders, setTraders] = useState([]);
  const [allTrades, setAllTrades] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [query, setQuery] = useState('');
  const [selectedTrader, setSelectedTrader] = useState(null);
  const [detail, setDetail] = useState(null);

  const loadAll = async () => {
    try {
      const [traderRes, tradeRes, logRes] = await Promise.all([
        api.fetchTraders(),
        api.fetchTrades(1, 300),
        api.fetchRiskLogs(),
      ]);

      const logs = normalizeArrayPayload(logRes);
      const mergedTrades = normalizeTrades(normalizeArrayPayload(tradeRes), logs);

      setTraders(normalizeArrayPayload(traderRes));
      setAllTrades(mergedTrades);
      setRiskLogs(logs);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    loadAll();
    const id = setInterval(loadAll, 2000);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });
    socket.on('fraud_alert', loadAll);
    socket.on('fraud_detected', loadAll);
    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);

    return () => {
      clearInterval(id);
      socket.disconnect();
    };
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return traders.filter((t) =>
      !q ||
      String(t.trader_id).includes(q) ||
      String(t.trader_name || '').toLowerCase().includes(q)
    );
  }, [traders, query]);

  useEffect(() => {
    if (!query.trim()) {
      setSelectedTrader(null);
      setDetail(null);
      return;
    }

    const exact = traders.find((t) => String(t.trader_id) === query.trim());
    if (!exact) return;

    setSelectedTrader(exact);
    setDetail(normalizeTraderDetail(allTrades, exact, riskLogs));
  }, [query, traders, allTrades, riskLogs]);

  return (
    <div className="page-wrap grid-bg">
      <div className="page-container">
        <div style={{ marginBottom: 24 }}>
          <h1 style={{ fontSize: 28, fontWeight: 900, margin: 0 }}>
            Trader <span className="neon-strong">Registry</span>
          </h1>
          <div style={{ color: '#82897c', marginTop: 8, fontSize: 16 }}>
            Search a trader by ID to view trade history, risk trend and trust score projection
          </div>
        </div>

        <div className="glass-strong" style={{ padding: 20, marginBottom: 22 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 220px', gap: 14 }}>
            <input
              className="search-input"
              placeholder="Search trader by exact ID, e.g. 14"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
            <div className="tag" style={{ justifyContent: 'center' }}>{filtered.length} traders</div>
          </div>
          <div style={{ color: '#687264', fontSize: 12, marginTop: 10 }}>
            Tip: type a trader ID exactly to load full profile analytics.
          </div>
        </div>

        <div className="grid-2">
          <div className="glass-strong" style={{ overflow: 'hidden' }}>
            <div style={{ padding: '18px 20px', fontWeight: 900, fontSize: 16 }}>Trader List</div>
            <div className="scroll-y" style={{ maxHeight: 620 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Name</th>
                    <th>Trust</th>
                    <th>Trades</th>
                    <th>Avg Risk</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.slice(0, 100).map((trader) => {
                    const traderTrades = allTrades.filter(
                      (t) => Number(t.seller_id) === Number(trader.trader_id) || Number(t.buyer_id) === Number(trader.trader_id)
                    );
                    const avgRisk = traderTrades.length
                      ? Math.round(traderTrades.reduce((s, t) => s + Number(t.risk_score || 0), 0) / traderTrades.length)
                      : 0;

                    return (
                      <tr
                        key={trader.trader_id}
                        onClick={() => {
                          setQuery(String(trader.trader_id));
                          setSelectedTrader(trader);
                          setDetail(normalizeTraderDetail(allTrades, trader, riskLogs));
                        }}
                        style={{ cursor: 'pointer' }}
                      >
                        <td style={{ color: '#7e8678', fontFamily: 'monospace' }}>#{trader.trader_id}</td>
                        <td>{trader.trader_name}</td>
                        <td>
                          <span className={badgeClass(100 - Number(trader.trust_score || 100))}>
                            {trader.trust_score ?? 100}
                          </span>
                        </td>
                        <td>{traderTrades.length}</td>
                        <td>{avgRisk}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>

          <div className="glass-strong" style={{ padding: 20 }}>
            {!selectedTrader || !detail ? (
              <div className="empty-state">
                Search a trader by ID to see the live profile, graph, trade history and trust trend.
              </div>
            ) : (
              <>
                <div style={{ display: 'flex', justifyContent: 'space-between', gap: 16, marginBottom: 18 }}>
                  <div>
                    <div style={{ color: '#7b8574', fontSize: 12, fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.08em' }}>
                      Trader Profile
                    </div>
                    <div style={{ fontSize: 26, fontWeight: 900, marginTop: 8 }}>{selectedTrader.trader_name}</div>
                    <div style={{ color: '#7f8779', marginTop: 6, fontSize: 13 }}>
                      ID #{selectedTrader.trader_id} • Registered {selectedTrader.registration_date || '—'}
                    </div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div className="neon-strong" style={{ fontSize: 34, fontWeight: 900 }}>
                      {selectedTrader.trust_score ?? 100}
                    </div>
                    <div style={{ color: '#6b7365', fontSize: 12 }}>current trust</div>
                  </div>
                </div>

                <div className="grid-3" style={{ marginBottom: 18 }}>
                  <div className="glass" style={{ padding: 16 }}>
                    <div className="soft" style={{ fontSize: 12, fontWeight: 800, textTransform: 'uppercase' }}>Total Trades</div>
                    <div style={{ fontSize: 28, fontWeight: 900, marginTop: 8 }}>{detail.totalTrades}</div>
                  </div>
                  <div className="glass" style={{ padding: 16 }}>
                    <div className="soft" style={{ fontSize: 12, fontWeight: 800, textTransform: 'uppercase' }}>Avg Risk</div>
                    <div style={{ fontSize: 28, fontWeight: 900, marginTop: 8, color: detail.avgRisk >= 70 ? '#ff5555' : detail.avgRisk >= 40 ? '#ffb020' : '#b8ff4f' }}>
                      {detail.avgRisk}
                    </div>
                  </div>
                  <div className="glass" style={{ padding: 16 }}>
                    <div className="soft" style={{ fontSize: 12, fontWeight: 800, textTransform: 'uppercase' }}>Predicted Trust</div>
                    <div className="neon-strong" style={{ fontSize: 28, fontWeight: 900, marginTop: 8 }}>
                      {detail.predictedTrust}
                    </div>
                  </div>
                </div>

                <div className="glass" style={{ padding: 16, marginBottom: 18 }}>
                  <div style={{ fontWeight: 900, marginBottom: 12 }}>Trades vs Risk vs Trust</div>
                  <TraderTrendChart points={detail.chartPoints} predictedTrust={detail.predictedTrust} />
                </div>

                <div className="glass" style={{ overflow: 'hidden' }}>
                  <div style={{ padding: '16px 16px 10px', fontWeight: 900 }}>Trade History</div>
                  <div className="scroll-y" style={{ maxHeight: 260 }}>
                    <table className="data-table">
                      <thead>
                        <tr>
                          <th>Trade</th>
                          <th>Role</th>
                          <th>Stock</th>
                          <th>Price</th>
                          <th>Qty</th>
                          <th>Risk</th>
                        </tr>
                      </thead>
                      <tbody>
                        {detail.trades.slice().reverse().map((t) => (
                          <tr key={t.trade_id}>
                            <td style={{ color: '#7c8578', fontFamily: 'monospace' }}>#{t.trade_id}</td>
                            <td>{Number(t.seller_id) === Number(selectedTrader.trader_id) ? 'Seller' : 'Buyer'}</td>
                            <td>{t.symbol || `#${t.stock_id}`}</td>
                            <td>${Number(t.price || 0).toFixed(2)}</td>
                            <td>{t.quantity}</td>
                            <td><span className={badgeClass(t.risk_score)}>{t.risk_score}</span></td>
                          </tr>
                        ))}
                        {!detail.trades.length && (
                          <tr>
                            <td colSpan="6">
                              <div className="empty-state">No trades for this trader yet.</div>
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
